values ('1b96dde0-599c-44dc-a98c-13742165570d','20000000-0000-4000-8000-000000000001','Cho đa giác đề $12$ đỉnh nội tiếp đường tròn tâm $O$. Chọn ngẫu nhiên $3$ đỉnh của đa giác đó. Các khẳng định sau đây đúng hay sai?','true_false','[{"value":"A","label":"Xác suất để 3 đỉnh được chọn tạo thành một tam giác có 3 cạnh đều là cạnh của đa giác đã cho bằng $0,25$"},{"value":"B","label":"Xác suất để 3 đỉnh được chọn tạo thành một tam giác không có cạnh nào là cạnh của đa giác đã cho bằng $\\displaystyle \\frac{{27}}{{55}}$"},{"value":"C","label":"Xác suất để 3 đỉnh được chọn tạo thành một tam giác có đúng 2 cạnh là cạnh của đa giác đã cho bằng $\\displaystyle \\frac{3}{{55}}$"}]'::jsonb,1,16,null,null,'Lựa chọn đúng hoặc sai cho từng phát biểu')
