values ('86611d02-cc26-4907-90f2-b7369a40d195','20000000-0000-4000-8000-000000000001','Cho $a > b > c > 0$, giá trị nhỏ nhất của hàm $f(x) = \left| {x - a} \right| + \left| {x - b} \right| + \left| {x - c} \right|$ là bao nhiêu?','single','[{"value":"A","label":"$a - c$."},{"value":"B","label":"$2a - b - c$."},{"value":"C","label":"$a + b - 2c$."},{"value":"D","label":"$a + b + c$."}]'::jsonb,1,17,null,null,null)
