values ('f9a2fc6d-803c-416a-8221-40c1ae58cc04','20000000-0000-4000-8000-000000000002','Theo đoạn [3], các nhận định sau đúng hay sai?','true_false','[{"value":"A","label":"Con người có xu hướng tương tác với tất cả các đối tác xã hội tiềm năng khi cho rằng những đối tác này có ý chí riêng."},{"value":"B","label":"Tận dụng mong muốn nhân cách hóa các thực thể của con người là mục đích chính của các AI tương tác hiện tại."},{"value":"C","label":"Nhu cầu kết nối xã hội là một đặc điểm quan trọng đối với sức khỏe tâm thần của con người."},{"value":"D","label":"Các bot AI cư xử giống như con người có thể tạo ra một loại tương tác giả tạo đối với con người."}]'::jsonb,1,3,'**Nên đối xử với chatbot như thế nào?**
