values ('de8c9f8f-64f5-43b6-9d52-76905e722182','20000000-0000-4000-8000-000000000002','Tiêu đề nào sau đây phù hợp với bài đọc nhất?','single','[{"value":"A","label":"Mùi vị và sự them ăn. Khám phá quan trọng của các nhà khoa học Mỹ."},{"value":"B","label":"Sự thèm ăn của con người. Thân não đóng vai trò them chốt."},{"value":"C","label":"Tế bào não: Tiềm năng ứng dụng điều chế thuốc giảm cân."},{"value":"D","label":"Mùi vị: Mảnh ghép còn thiếu trong kiểm soát sự thèm ăn."}]'::jsonb,1,19,'**Ngữ liệu 2**
