values ('d14a5506-bd36-42ca-b264-5fcaeb6fdff7','20000000-0000-4000-8000-000000000003','Phát biểu sau đây đúng hay sai?','true_false','[{"value":"A","label":"Cây chỉ hấp thụ được muối khoáng ở dạng hòa tan trong nước."},{"value":"B","label":"Muối khoáng tồn tại trong đất đều ở dạng hợp chất và rễ cây chỉ hấp thụ dưới dạng hợp chất."},{"value":"C","label":"Bón phân dư thừa sẽ gây độc hại cho cây."},{"value":"D","label":"Dư lượng phân bón làm tăng độ phì nhiêu của đất."}]'::jsonb,1,29,'**DINH DƯỠNG KHOÁNG VÀ PHÂN BÓN Ở THỰC VẬT**
