insert into public.exam_questions (id,section_id,prompt,question_type,options,points,sort_order,passage,media_url,instruction)
values ('0230bdd9-89cf-41b2-9d69-4ff36ed06b37','20000000-0000-4000-8000-000000000003','Khi so sánh tỷ lệ diện tích bề mặt trên thể tích của mẫu SK và LK, ta có:','single','[{"value":"A","label":"LK gấp 03 lần SK"},{"value":"B","label":"LK gấp 09 lần SK"},{"value":"C","label":"SK gấp 09 lần LK"},{"value":"D","label":"SK gấp 03 lần LK"}]'::jsonb,1,39,'**Quá trình chuyển hóa của kim chi của cải**
Kim chi là một loại thực phẩm lên men truyền thống của Hàn Quốc và ngày nay được tiêu thụ rộng rãi trên toàn thế giới. Kim chi củ cải (kkakdugi) là loại kim chi sử dụng củ cải làm nguyên liệu chính được thái thành các miếng đều nhau. Dựa trên các nghiên cứu trước đây, sự khác biệt về kích thước của các nguyên liệu sẽ ảnh hưởng đến quá trình lên men kim chi củ cải. Trong thí nghiệm này, củ cải được cắt thành các khối có kích thước lần lượt là cỡ nhỏ ($SK$): 1 x 1 x 1 cm, cỡ vừa ($MK$): $2\;x\;2\;x\;2$ cm và cỡ lớn ($LK$) 3 x 3 x 3 cm. Sau đó, củ cải được trộn với hỗn hợp gia vị gồm bột ớt đỏ, tỏi, gừng, hành lá, muối, đường. Hỗn hợp củ cải và gia vị được để ở nhiệt độ $20^\circ C$ trong $6$ giờ để kích thích quá trình lên men, sau đó giữ ở $4^\circ C$ trong $50$ ngày. 

Các tính chất của kim chi được đánh giá bao gồm: $pH$, axit tổng số, độ cứng. Kết quả được thể hiện ở hình 1. Hàm lượng axit tổng số trong kim chi được xác định bằng cách trung hòa bởi $NaOH$ $0,1N$ và được biểu diễn bằng $\% $ axit lactic. Hệ vi khuẩn chủ yếu trong quá trình lên men được xác định thuộc các chi Lactobacillus, Leuconostoc và Weissella.
***Hình 1: Biến đổi một số thông số của kim chi chủ cái trong thời gian lên men***

$/image_{https://api-course.hethonglab.com/static/a75b4e79-3eef-40e6-a009-9fae1dd4c86d.png}_{center}_{100}_{block}$

